sksl:
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float distortion;
uniform float spread;
uniform float chromaMix;
uniform float scale;
uniform float speed;
uniform float blurStrength;
layout(color) uniform half4 highlights;
layout(color) uniform half4 midtones;
layout(color) uniform half4 shadows;
        float2 hash2(float2 p) {
            p = float2(dot(p, float2(127.1, 311.7)), dot(p, float2(269.5, 183.3)));
            return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
        }
        float noise(float2 p) {
            float2 i = floor(p);
            float2 f = fract(p);
            float2 u = f * f * (3.0 - 2.0 * f);
            return mix(mix(dot(hash2(i + float2(0.0, 0.0)), f - float2(0.0, 0.0)),
                           dot(hash2(i + float2(1.0, 0.0)), f - float2(1.0, 0.0)), u.x),
                       mix(dot(hash2(i + float2(0.0, 1.0)), f - float2(0.0, 1.0)),
                           dot(hash2(i + float2(1.0, 1.0)), f - float2(1.0, 1.0)), u.x), u.y);
        }
        void amzRender() {
            float2 uv = amzLayerNorm().xy;
            float2 noiseUV = uv;
            noiseUV.x *= layer.x / layer.y;
            float n = noise(noiseUV * scale + time * speed);
            float n2 = noise(noiseUV * scale + time * speed + float2(17.3, 2.9));
            float2 disp = float2(n, n2) * distortion;
            float3 accumulatedColor = float3(0.0);
            float totalWeight = 0.0;
            float accumulatedAlpha = 0.0;
            const int samples = 16;
            for (int i = 0; i < samples; i++) {
                float t = float(i) / float(samples - 1);
                float2 blurOffset = disp * (t - 0.5) * blurStrength;
                float2 currentDisp = disp + blurOffset;
                float2 uvR = uv + currentDisp * (1.0 + spread * 5.0);
                float2 uvG = uv + currentDisp;
                float2 uvB = uv + currentDisp * (1.0 - spread * 5.0);
                float r = amzTexture(0, uvR).r * highlights.r;
                float g = amzTexture(0, uvG).g * midtones.g;
                float b = amzTexture(0, uvB).b * shadows.b;
                float a = amzTexture(0, uvG).a;
                float3 col = float3(r, g, b);
                float w = 1.0;
                accumulatedColor += col * w;
                accumulatedAlpha += a * w;
                totalWeight += w;
            }
            float3 chromaticBlurred = accumulatedColor / totalWeight;
            float finalAlpha = accumulatedAlpha / totalWeight;
            float2 centerUV = uv + disp;
            float3 standardColor = amzTexture(0, centerUV).rgb;
            float3 finalColor = mix(standardColor, chromaticBlurred, chromaMix);
            amzOutput = float4(finalColor, finalAlpha);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
